import{_ as t,o,c as d,a0 as a}from"./chunks/framework.CIbwkeYd.js";const g=JSON.parse('{"title":"Front-end navigation map","description":"","frontmatter":{},"headers":[],"relativePath":"FrontEndNavigation.md","filePath":"FrontEndNavigation.md"}'),c={name:"FrontEndNavigation.md"};function n(s,e,r,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="front-end-navigation-map" tabindex="-1">Front-end navigation map <a class="header-anchor" href="#front-end-navigation-map" aria-label="Permalink to &quot;Front-end navigation map&quot;">​</a></h1><p>How a request becomes a screen today, on the two hosts that matter (<code>cleaker.me</code> and <code>netget.site</code>), what the target model is, and where they differ. Written 2026-09-21 from code and from a read-only copy of the VM&#39;s installed <code>netget_app.conf</code>. Nothing here was changed by writing it.</p><p>Legend: <strong>[code]</strong> read in the repository, <strong>[conf]</strong> read in the VM&#39;s installed nginx configuration, <strong>[not verified]</strong> inferred, not observed.</p><h2 id="_1-target-model-decided-not-yet-implemented" tabindex="-1">1. Target model (decided, not yet implemented) <a class="header-anchor" href="#_1-target-model-decided-not-yet-implemented" aria-label="Permalink to &quot;1. Target model (decided, not yet implemented)&quot;">​</a></h2><ul><li><code>netget.site</code> points at <strong>the same namespace as <code>cleaker.me</code></strong>. Administration may be its <em>initial screen</em>, but it keeps the tree&#39;s routes: <code>netget.site/x</code> and <code>cleaker.me/x</code> are the same <code>x</code>.</li><li>A route resolves to <strong>the component the GUI document declares for that route</strong>, not to one fixed landing.</li><li>Two different things, not to be merged: <ul><li><code>/.gateway/*</code> — the gateway&#39;s <strong>control API</strong>.</li><li>Administrative <strong>screens</strong> — components and routes declared in the GUI document. They do not have to use the API&#39;s prefix.</li></ul></li><li>A launcher that names a fixed address (<code>http://local.cleaker</code>) contradicts the model: it must use the resolved context and transport.</li><li>Unifying the two shells belongs to the doors migration, not to the small presentation fix.</li></ul><h2 id="_2-today" tabindex="-1">2. Today <a class="header-anchor" href="#_2-today" aria-label="Permalink to &quot;2. Today&quot;">​</a></h2><h3 id="_2-1-one-bundle-three-roles" tabindex="-1">2.1 One bundle, three roles <a class="header-anchor" href="#_2-1-one-bundle-three-roles" aria-label="Permalink to &quot;2.1 One bundle, three roles&quot;">​</a></h3><p><code>frontend_local</code> builds one bundle (served from <code>assets/main-server-ui/dist</code>). <code>frontendRole({host, boot})</code> [code: <code>frontend_local/src/session/providerBoot.js:46</code>] picks the role:</p><table tabindex="0"><thead><tr><th>Condition (first match wins)</th><th>Role</th><th>Renders</th></tr></thead><tbody><tr><td>host is <code>local.cleaker</code></td><td><code>cleaker</code></td><td><code>CleakerLanding</code>, whole page</td></tr><tr><td>host is <code>local.host</code></td><td><code>host</code></td><td><code>HostSurface</code></td></tr><tr><td>a provider boot exists and the host is the namespace or a handle under it</td><td><code>cleaker</code></td><td><code>CleakerLanding</code></td></tr><tr><td>a provider boot exists and its monad is not a gateway monad</td><td><code>cleaker</code></td><td><code>CleakerLanding</code></td></tr><tr><td>anything else (no boot, or a gateway monad on a non-namespace host)</td><td><code>gateway</code></td><td><code>NetGetShell</code></td></tr></tbody></table><p>The boot (<code>window.__MONAD_NAMESPACE_PROVIDER_BOOT__</code>) is injected by the monad when <em>it</em> hands out <code>index.html</code>.</p><h3 id="_2-2-cleaker-me-and-www-and-handle-cleaker-me" tabindex="-1">2.2 <code>cleaker.me</code> (and <code>www</code>, and <code>&lt;handle&gt;.cleaker.me</code>) <a class="header-anchor" href="#_2-2-cleaker-me-and-www-and-handle-cleaker-me" aria-label="Permalink to &quot;2.2 `cleaker.me` (and `www`, and `&lt;handle&gt;.cleaker.me`)&quot;">​</a></h3><ul><li>nginx [conf]: one <code>server</code> with a single <code>location /</code> → <code>surface_proxy.lua</code> → the namespace&#39;s monad. <strong>No other location</strong>: every path goes to the monad.</li><li>SPA role <code>cleaker</code> → <code>CleakerLanding</code>. Routes come from the GUI document [code: <code>packages/GUI/Typescript/src/runtime/GUI.document.json</code>]: <code>/</code>, <code>/users</code>, <code>/blockchain</code>, <code>/url</code>, <code>/keychain</code>, <code>/keychain/claim</code>, <code>/keychain/admin-sign</code>, <code>/netget</code>.</li><li>Sidebar [code: <code>CleakerLanding.tsx:2160</code>]: Home, the items the namespace declares, Keychain (only with a session), Netget → <code>/netget</code>.</li><li><code>/netget</code> mounts <code>MainServerView</code> (public status) and <code>GatewaySetup</code> (claim) against the <strong>confirmed root endpoint</strong> (the origin already verified for the sidebar), not a re-derived address.</li></ul><h3 id="_2-3-netget-site" tabindex="-1">2.3 <code>netget.site</code> <a class="header-anchor" href="#_2-3-netget-site" aria-label="Permalink to &quot;2.3 `netget.site`&quot;">​</a></h3><ul><li>nginx [conf]: one <code>server</code> with ~60 top-level <code>location</code>s (section 3) and, last, <code>location /</code> serving the static SPA with <code>try_files $uri $uri/ /index.html</code>. Nothing injects a boot, so the role is <code>gateway</code>.</li><li>SPA role <code>gateway</code> → <code>NetGetShell</code> [code: <code>frontend_local/src/App.jsx</code>]:</li></ul><table tabindex="0"><thead><tr><th>Route</th><th>Screen</th></tr></thead><tbody><tr><td><code>/</code></td><td><code>GatewayEntry</code> → <code>GatewaySetup</code> (endpoint <code>&quot;&quot;</code>, same origin)</td></tr><tr><td><code>/home</code></td><td><code>Home</code> → <code>GatewayDashboard</code> (<code>/gateway-identity</code>, <code>/apps</code>, polled every 5 s)</td></tr><tr><td><code>/domains</code></td><td><code>Domains</code> (REST: <code>/domains</code>, <code>/add-domain</code>, <code>/delete-domain</code>, <code>/provision-cert</code>)</td></tr><tr><td><code>/logs</code></td><td><code>Logs</code> (REST: <code>/logs</code>)</td></tr><tr><td><code>/terms-and-conditions</code>, <code>/privacy-policy</code></td><td>static pages</td></tr></tbody></table><ul><li>Sidebar: Home, Dashboard, Domains, Logs. Footer launchers: Dev Tools, Theme, Frontend Mode, <code>.me</code>.</li><li>There is <strong>no <code>/netget</code>, <code>/keychain</code>, <code>/users</code>, <code>/blockchain</code>, <code>/url</code></strong> route in this shell, and no route for any path of the namespace tree. A path that nginx lets through falls back to <code>index.html</code>; the shell has no matching <code>&lt;Route&gt;</code>, so the content area renders nothing <strong>[not verified in a browser]</strong>.</li><li>The <code>.me</code> launcher is fixed to <code>http://local.cleaker</code> [code: <code>App.jsx:136</code>] — the contradiction named in section 1.</li></ul><h3 id="_2-4-where-the-two-disagree" tabindex="-1">2.4 Where the two disagree <a class="header-anchor" href="#_2-4-where-the-two-disagree" aria-label="Permalink to &quot;2.4 Where the two disagree&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><code>cleaker.me</code></th><th><code>netget.site</code></th></tr></thead><tbody><tr><td>Same tree path gives the same answer</td><td>yes (every path → monad)</td><td><strong>no</strong></td></tr><tr><td>Gateway status screen</td><td><code>MainServerView</code> (<code>/netget</code>)</td><td><code>GatewayDashboard</code> (<code>/home</code>) — a different component</td></tr><tr><td>Claim screen</td><td><code>GatewaySetup</code> at <code>/netget</code></td><td><code>GatewaySetup</code> at <code>/</code></td></tr><tr><td>Session / keychain</td><td>yes</td><td>none in this shell</td></tr><tr><td><code>.me</code> launcher context</td><td>resolved</td><td>fixed <code>local.cleaker</code></td></tr><tr><td>Monad link target</td><td>—</td><td><code>/monads/&lt;name&gt;</code> (old internal alias; public form is <code>/apps/&lt;name&gt;</code>) [code: <code>Home.jsx:26</code>]</td></tr></tbody></table><h2 id="_3-paths-netget-site-answers-before-the-namespace-can-conf" tabindex="-1">3. Paths <code>netget.site</code> answers before the namespace can [conf] <a class="header-anchor" href="#_3-paths-netget-site-answers-before-the-namespace-can-conf" aria-label="Permalink to &quot;3. Paths `netget.site` answers before the namespace can [conf]&quot;">​</a></h2><p>These exist as nginx locations on the <code>netget.site</code> server and therefore <strong>shadow</strong> a tree path of the same name there, while <code>cleaker.me</code> would pass the same path to the monad:</p><ul><li>Static/UI: <code>/assets/</code>, <code>/media/</code>, <code>/networks</code>, <code>/deploy</code>, and any path ending in <code>.css .js .png .jpg .jpeg .gif .ico .svg .woff .woff2 .ttf .eot</code>.</li><li>Gateway API: <code>/gateway-identity</code>, <code>/apps</code> (+ <code>/apps/report|release|restart-all|catalog…</code>, <code>/apps/&lt;name&gt;…</code>), <code>/monads/&lt;name&gt;…</code>, <code>/entrypoints</code>, <code>/surfaces</code>, <code>/main-server-namespace</code>, <code>/setup/*</code>, <code>/admin-session/*</code>, <code>/domains</code> (+ <code>/domains/&lt;x&gt;/subdomains</code>, <code>/domains/metadata</code>), <code>/add-domain</code>, <code>/update-domain</code>, <code>/delete-domain</code>, <code>/provision-cert</code>, <code>/logs</code>, <code>/explain</code>, <code>/inspect</code>, <code>/openresty-status|restart|stop</code>, <code>/dev-server-status|start|stop</code>, <code>/healthcheck</code>, <code>/ip-info</code>, <code>/port-info</code>.</li><li>Identity/session: <code>/me/*</code>, <code>/check-auth</code>, <code>/logout</code>, <code>/cleaker/resolve</code>, <code>/nrp</code>, <code>/@…</code>.</li></ul><p>Consequence for the target model: the gateway API has to move under <code>/.gateway/*</code> (or otherwise stop sharing names with tree paths) before <code>netget.site/x</code> can equal <code>cleaker.me/x</code>. <code>/domains</code> and <code>/logs</code> are today both an SPA page and an API route on the same path (nginx tells them apart by <code>Sec-Fetch-Mode: navigate</code>, which a browser sets only on real navigations, and rewrites those to <code>index.html</code>) — the clearest case of the API and the screen sharing a name.</p><h2 id="_4-gatewaydashboard-netget-site-home-—-review" tabindex="-1">4. <code>GatewayDashboard</code> (netget.site <code>/home</code>) — review <a class="header-anchor" href="#_4-gatewaydashboard-netget-site-home-—-review" aria-label="Permalink to &quot;4. `GatewayDashboard` (netget.site `/home`) — review&quot;">​</a></h2><p>Files: <code>gui/src/compounds/GatewayDashboard/GatewayDashboard.tsx</code>, <code>gui/src/molecules/GatewayCard/GatewayCard.tsx</code>, <code>gui/src/compounds/MonadMesh/MonadMesh.tsx</code>. Same criterion as the <code>MainServerView</code> fix: an <strong>absent</strong> fact must not be shown as a <strong>negative</strong> fact, and different names must not share a field.</p><table tabindex="0"><thead><tr><th>#</th><th>Where</th><th>What it does</th><th>Why it misleads</th></tr></thead><tbody><tr><td>1</td><td><code>GatewayDashboard.tsx:49</code></td><td><code>adminCount: data.adminCount ?? 0</code></td><td>A response without the count shows &quot;Admins 0&quot;. This is the original <code>adminCount: 0</code> symptom from the Lua handler.</td></tr><tr><td>2</td><td><code>GatewayDashboard.tsx:48</code></td><td><code>bootstrapped: !!data.bootstrapped</code></td><td>A missing field reads as &quot;unclaimed&quot;.</td></tr><tr><td>3</td><td><code>GatewayDashboard.tsx:46</code></td><td><code>gatewayId: data.gatewayId ?? &#39;unknown&#39;</code></td><td>Presents &quot;unknown&quot; as if it were an id.</td></tr><tr><td>4</td><td><code>GatewayCard.tsx:10–11,49</code></td><td>Title is <code>gatewayId</code>, documented as &quot;hostname / node ID&quot;</td><td>Two different facts in one field. The contract now carries <code>hostname</code> separately; the card ignores it.</td></tr><tr><td>5</td><td><code>GatewayCard.tsx:64</code></td><td>Owner shown only as a hash (<code>HashLabel</code>)</td><td>The contract carries <code>ownerUsername</code>; <code>MainServerView</code> shows it, this card does not — the same gateway reads differently on the two hosts.</td></tr><tr><td>6</td><td><code>GatewayCard.tsx:71</code></td><td>&quot;Listening on <code>scheme://ip:port</code>&quot;</td><td><code>ip</code> is the machine&#39;s local IPv4 from the contract, not what nginx was verified to listen on. The label claims more than the field says.</td></tr><tr><td>7</td><td><code>GatewayCard.tsx:21,103</code></td><td><code>updatedAt</code> typed as ISO string, labelled &quot;snapshot&quot;</td><td>The contract sends epoch milliseconds (still renders); &quot;snapshot&quot; describes the cache, while the authority is the monad&#39;s canonical branch.</td></tr><tr><td>8</td><td><code>GatewayCard.tsx:2</code></td><td>Header says it reads <code>gateway-claims.json</code></td><td>Out of date: that file is a cache of the canonical branch.</td></tr><tr><td>9</td><td><code>MonadMesh.tsx:47</code></td><td><code>Array.isArray(data.apps) ? data.apps : []</code></td><td>A 200 without <code>apps</code> shows &quot;No live monads registered&quot; (a non-2xx or non-JSON reply does show its error).</td></tr><tr><td>10</td><td><code>MonadMesh.tsx:102–103</code></td><td><code>trust ?? &#39;guest&#39;</code>, <code>exposure ?? &#39;loopback&#39;</code></td><td>A missing value is shown as a definite one; &quot;loopback&quot; states the monad is not exposed.</td></tr><tr><td>11</td><td><code>MonadMesh.tsx:83</code></td><td>Hint says to call <code>netget.registerApp()</code></td><td>Stale instruction.</td></tr><tr><td>12</td><td><code>Home.jsx:26</code></td><td>Monad click → <code>window.location.href = /monads/&lt;name&gt;</code></td><td>Leaves the SPA through the old alias; the public form is <code>/apps/&lt;name&gt;</code>.</td></tr></tbody></table><p>Not a defect, worth knowing: fetch failures do show the real message (&quot;404 Not Found&quot;), which is the honest behaviour <code>MainServerView</code> needed for <code>/entrypoints</code>.</p><p>Findings 1–3 are fixed locally: missing gateway IDs, claim status, and admin counts now show explicit unavailable states. An explicit <code>false</code> still means unclaimed and an explicit <code>0</code> still shows zero. <code>GatewayDashboard</code> rejects malformed values for these three fields. The <code>MissingIdentityFields</code> story covers a successful but incomplete response. Two neighbours of the same class are closed as well: a missing <code>owner</code> shows &quot;Owner unavailable&quot; (an explicit <code>null</code> still shows &quot;not set&quot;) and a missing <code>scopes</code> shows &quot;Not available&quot; (an explicit <code>[]</code> still shows 0). The mapping lives in <code>gui/src/compounds/GatewayDashboard/identityView.ts</code> and is covered by <code>tests/gateway-identity-view.test.ts</code> (part of <code>npm test</code>). Findings 4–12 remain pending; this does not imply deployment.</p><h2 id="_5-what-is-still-unknown" tabindex="-1">5. What is still unknown <a class="header-anchor" href="#_5-what-is-still-unknown" aria-label="Permalink to &quot;5. What is still unknown&quot;">​</a></h2><ul><li>What <code>netget.site/&lt;unknown path&gt;</code> renders in a browser (section 2.3 is from the route table).</li><li>Whether the monad, when it serves <code>index.html</code> for <code>cleaker.me/&lt;any path&gt;</code>, always falls back to the SPA for paths the tree does not declare (it worked live for <code>/netget</code>; the general rule is not read).</li><li>Whether any client still depends on the API being reachable at the top-level paths listed in section 3 (<code>/domains</code>, <code>/apps</code>, <code>/gateway-identity</code>, <code>/setup/*</code>, <code>/admin-session/*</code>); moving them needs that inventory.</li></ul><h2 id="_6-order-of-work-implied-nothing-started" tabindex="-1">6. Order of work implied (nothing started) <a class="header-anchor" href="#_6-order-of-work-implied-nothing-started" aria-label="Permalink to &quot;6. Order of work implied (nothing started)&quot;">​</a></h2><ol><li>Inventory consumers of the section 3 paths (GUI, CLI, monads&#39; registration, tests, docs).</li><li>Introduce <code>/.gateway/*</code> as the control API next to the existing paths; move consumers; then retire the old names on the <code>netget.site</code> server.</li><li>Declare the administrative screens in the GUI document as routes with their own components.</li><li>Make <code>netget.site</code> resolve tree routes through the same document as <code>cleaker.me</code>, with admin as the initial screen; drop the fixed <code>local.cleaker</code> launcher in favour of the resolved context and transport.</li><li>Apply the section 4 corrections (independent of 1–4).</li></ol>',31)])])}const p=t(c,[["render",n]]);export{g as __pageData,p as default};
